#!/bin/zsh
set -euo pipefail
cd -- "${0:A:h:h}"
[[ -f package.json ]] || { print -u2 'プロジェクトルートを確認してください'; exit 1; }
git rev-parse --is-inside-work-tree >/dev/null
if [[ -n "$(git status --porcelain --untracked-files=all -- . ':!gemini-scripts')" ]]; then
  print -u2 'gemini-scripts以外の未コミット変更を先に整理してください。'
  exit 1
fi
node <<'NODE'
const fs = require('node:fs');
const edits = {"src/main/repositories/settings-repository.ts": [["  workspace: 'workspace'", "  workspace: 'workspace',\n  windowState: 'windowState'"]], "src/main/window.ts": [["export function createMainWindow(presentation: WindowPresentation = { kind: 'normal' }): BrowserWindow {", "export function createMainWindow(presentation: WindowPresentation = { kind: 'normal' }, restored?: { compact: boolean; bounds: Rectangle | undefined }): BrowserWindow {"], ["...(presentation.kind === 'inactive' ? presentation.bounds : DEFAULT_WINDOW_SIZE),", "...(presentation.kind === 'inactive' ? presentation.bounds : restored?.bounds ?? DEFAULT_WINDOW_SIZE),"], ["    minWidth: MIN_WINDOW_WIDTH,", "    minWidth: restored?.compact ? 240 : MIN_WINDOW_WIDTH,"]], "src/main/index.ts": [["import { tmpdir } from 'node:os'", "import { tmpdir } from 'node:os'\nimport { createWindowState } from './lifecycle/window-state'"], ["let mainWindow: BrowserWindow | null = null", "let windowState: ReturnType<typeof createWindowState> | null = null\nlet mainWindow: BrowserWindow | null = null"], ["    mainWindow = createMainWindow(windowPresentation)", "    if (!database) throw new Error('DBが初期化されていません')\n    windowState ??= createWindowState(createSettingsRepository(database), MIN_WINDOW_WIDTH)\n    const restoring = windowPresentation.kind === 'normal'\n    mainWindow = createMainWindow(windowPresentation, restoring ? { compact: windowState.compact, bounds: windowState.restoreBounds() } : undefined)\n    // 自動UIテストでは従来の起動サイズと表示方法を維持する。\n    if (restoring) windowState.attach(mainWindow)"], ["    setCompact: (compact) => {\n      const win = mainWindow\n      if (!win || win.isDestroyed()) throw new Error('ウィンドウがありません')\n      win.setMinimumSize(compact ? 240 : MIN_WINDOW_WIDTH, MIN_WINDOW_HEIGHT)\n      if (!compact) {\n        const { width, height } = win.getBounds()\n        if (width < MIN_WINDOW_WIDTH) win.setSize(MIN_WINDOW_WIDTH, height)\n      }\n      return null\n    },", "    setCompact: (compact) => {\n      if (windowPresentation.kind !== 'normal') {\n        if (!mainWindow || mainWindow.isDestroyed()) throw new Error('ウィンドウがありません')\n        mainWindow.setMinimumSize(compact ? 240 : MIN_WINDOW_WIDTH, MIN_WINDOW_HEIGHT)\n      } else {\n        if (!windowState) throw new Error('ウィンドウ設定が初期化されていません')\n        windowState.setCompact(compact)\n      }\n      return null\n    },"], ["    name: APP_IDENTITY.displayName,", "    compact: windowPresentation.kind === 'normal' ? windowState?.compact ?? false : false,\n    name: APP_IDENTITY.displayName,"]], "src/shared/contracts/ipc.ts": [["export type AppInfo = {", "export type AppInfo = {\n  compact?: boolean"]], "src/renderer/src/layouts/AppFrame.tsx": [["import { AppShell } from './shell/AppShell'", "import { AppShell } from './shell/AppShell'\nimport { appInfoQueryOptions } from '../features/app-info/app-info-query'"], ["  const workspace = useQuery(workspaceSettingsQueryOptions)", "  const workspace = useQuery(workspaceSettingsQueryOptions)\n  const appInfo = useQuery(appInfoQueryOptions)"], ["  if (workspace.isPending) {", "  if (workspace.isPending || appInfo.isPending) {"], ["        <AppShell />", "        <AppShell initialCompact={appInfo.data?.compact ?? false} />"]], "src/renderer/src/layouts/shell/AppShell.tsx": [["export function AppShell() {", "export function AppShell({ initialCompact = false }: { initialCompact?: boolean }) {"], ["  const [compact, setCompact] = useState(false)", "  const [compact, setCompact] = useState(initialCompact)"]]};
const newPath = 'src/main/lifecycle/window-state.ts';
if (fs.existsSync(newPath)) throw new Error(`既存ファイルは上書きしません: ${newPath}`);
const output = new Map();
for (const [path, replacements] of Object.entries(edits)) {
  let source = fs.readFileSync(path, 'utf8');
  for (const [before, after] of replacements) {
    if (source.split(before).length !== 2) throw new Error(`対象コードが一致しません。001〜004適用後のコードを確認してください: ${path}\n${before}`);
    source = source.replace(before, after);
  }
  output.set(path, source);
}
output.set(newPath, "import { screen, type BrowserWindow, type Rectangle } from 'electron'\nimport { z } from 'zod'\nimport type { SettingsRepository } from '../repositories/settings-repository'\n\nconst boundsSchema = z.object({\n  x: z.number().int().min(-100000).max(100000),\n  y: z.number().int().min(-100000).max(100000),\n  width: z.number().int().min(240).max(30000),\n  height: z.number().int().min(480).max(30000)\n})\nconst stateSchema = z.object({ version: z.literal(1), compact: z.boolean(), bounds: boundsSchema })\ntype State = z.infer<typeof stateSchema>\n\nexport function createWindowState(repository: SettingsRepository, normalMinimum: number) {\n  let state: State | null = null\n  try {\n    const row = repository.get('windowState')\n    if (row) {\n      const parsed = stateSchema.safeParse(JSON.parse(row.value))\n      if (parsed.success) state = parsed.data\n      else console.warn('[window-state] 保存値が不正なため既定値を使用します')\n    }\n  } catch (error) { console.error('[window-state] 読み込みに失敗しました', error) }\n  let compact = state?.compact ?? false\n  let win: BrowserWindow | null = null\n  let timer: ReturnType<typeof setTimeout> | null = null\n\n  const restoreBounds = (): Rectangle | undefined => {\n    if (!state) return undefined\n    const saved = state.bounds\n    const area = screen.getDisplayMatching(saved).workArea\n    const width = Math.max(compact ? 240 : normalMinimum, Math.min(saved.width, area.width))\n    const height = Math.max(480, Math.min(saved.height, area.height))\n    return {\n      width, height,\n      x: Math.round(Math.max(area.x, Math.min(saved.x, area.x + area.width - width))),\n      y: Math.round(Math.max(area.y, Math.min(saved.y, area.y + area.height - height)))\n    }\n  }\n  const save = () => {\n    if (timer) clearTimeout(timer)\n    timer = null\n    if (!win || win.isDestroyed()) return\n    const bounds = win.isMaximized() || win.isFullScreen() || win.isMinimized() ? win.getNormalBounds() : win.getBounds()\n    const next: State = { version: 1, compact, bounds }\n    repository.upsert({ key: 'windowState', value: JSON.stringify(next), updatedAt: new Date().toISOString() })\n    state = next\n  }\n  const safeSave = () => {\n    try { save() } catch (error) { console.error('[window-state] 保存に失敗しました', error) }\n  }\n  const schedule = () => {\n    if (timer) clearTimeout(timer)\n    timer = setTimeout(safeSave, 150)\n  }\n  return {\n    get compact() { return compact },\n    restoreBounds,\n    attach(window: BrowserWindow) {\n      win = window\n      window.on('move', schedule)\n      window.on('resize', schedule)\n      window.on('close', safeSave)\n      window.once('closed', () => {\n        if (timer) clearTimeout(timer)\n        timer = null\n        win = null\n      })\n    },\n    setCompact(next: boolean) {\n      if (!win || win.isDestroyed()) throw new Error('ウィンドウがありません')\n      const previous = compact\n      const bounds = win.getBounds()\n      try {\n        compact = next\n        win.setMinimumSize(next ? 240 : normalMinimum, 480)\n        if (!next && bounds.width < normalMinimum) win.setSize(normalMinimum, bounds.height)\n        save()\n      } catch (error) {\n        compact = previous\n        win.setMinimumSize(previous ? 240 : normalMinimum, 480)\n        win.setBounds(bounds)\n        throw error\n      }\n    }\n  }\n}\n");
for (const [path, source] of output) {
  fs.writeFileSync(path, source);
  console.log(`更新: ${path}`);
}
NODE
npm run typecheck
npm run build
git diff --check

git add .
git commit -m '表示モードとウィンドウサイズ位置を保存復元'
